<?php require __DIR__.'/config/config.php';require __DIR__.'/config/helpers.php';require_login();if(current_user()['role']!=='client'){flash('warning','Connectez-vous avec un compte client pour réserver.');redirect('index.php');}verify_csrf();$roomId=(int)($_GET['room']??$_POST['room_id']??0);$q=$pdo->prepare("SELECT r.*,h.nom hotel_nom,h.id hotel_id,h.ville FROM rooms r JOIN hotels h ON h.id=r.hotel_id WHERE r.id=? AND r.actif=1 AND h.statut='valide'");$q->execute([$roomId]);$room=$q->fetch();if(!$room){flash('danger','Chambre introuvable ou indisponible.');redirect('index.php');}$error='';$total=0;$nights=0;if($_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['arrivee']??'';$d=$_POST['depart']??'';$people=max(1,(int)($_POST['personnes']??1));$qty=max(1,(int)($_POST['nombre_chambres']??1));$today=date('Y-m-d');if(!$a||!$d||$a<$today||$d<=$a){$error='Choisissez une date d’arrivée valide et un départ postérieur à l’arrivée.';}elseif($people>(int)$room['capacite']){$error='La capacité maximale de cette chambre est de '.$room['capacite'].' personne(s).';}elseif($qty>(int)$room['quantite']){$error='Le nombre de chambres demandé dépasse la quantité configurée.';}else{$nights=(int)((strtotime($d)-strtotime($a))/86400);$total=$nights*(float)$room['prix_nuit']*$qty;$q=$pdo->prepare("SELECT COUNT(*) FROM reservations WHERE room_id=? AND statut NOT IN ('annulee','refusee') AND date_arrivee < ? AND date_depart > ?");$q->execute([$roomId,$d,$a]);if((int)$q->fetchColumn()+$qty>(int)$room['quantite']){$error='Cette chambre n’est pas disponible pour toutes les dates choisies.';}else{$code='RES-'.date('Y').'-'.strtoupper(bin2hex(random_bytes(4)));$q=$pdo->prepare("INSERT INTO reservations(code,user_id,hotel_id,room_id,date_arrivee,date_depart,personnes,nombre_chambres,prix_nuit,total,statut,mode_paiement) VALUES(?,?,?,?,?,?,?,?,?,?, 'attente','paiement_hotel')");$q->execute([$code,current_user()['id'],$room['hotel_id'],$roomId,$a,$d,$people,$qty,$room['prix_nuit'],$total]);$rid=(int)$pdo->lastInsertId();$q=$pdo->prepare('SELECT user_id FROM hotels WHERE id=?');$q->execute([$room['hotel_id']]);$hid=(int)$q->fetchColumn();$q=$pdo->prepare('INSERT INTO notifications(user_id,titre,message) VALUES(?,?,?)');$q->execute([$hid,'Nouvelle réservation','Une réservation '.$code.' est en attente de traitement.']);flash('success','Demande de réservation créée : '.$code.'. Le paiement n’est pas effectué en ligne.');redirect('client/index.php');}}}$pageTitle='Réserver une chambre';require __DIR__.'/includes/header.php';?><section class="auth-wrap"><form class="auth-card" method="post"><?=csrf_field()?><input type="hidden" name="room_id" value="<?=$roomId?>"><span class="eyebrow">VOTRE PROCHAIN SÉJOUR</span><h1>Réserver une chambre</h1><p><?=e($room['hotel_nom'])?> · <?=e($room['nom'])?> · <?=money($room['prix_nuit'])?> / nuit</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><label class="form-label">Date d’arrivée</label><input class="form-control mb-3" type="date" name="arrivee" min="<?=date('Y-m-d')?>" required value="<?=e($_POST['arrivee']??'')?>"><label class="form-label">Date de départ</label><input class="form-control mb-3" type="date" name="depart" min="<?=date('Y-m-d',strtotime('+1 day'))?>" required value="<?=e($_POST['depart']??'')?>"><div class="row"><div class="col-6"><label class="form-label">Voyageurs</label><input class="form-control mb-3" type="number" name="personnes" min="1" max="<?=$room['capacite']?>" value="<?=e($_POST['personnes']??1)?>" required></div><div class="col-6"><label class="form-label">Chambres</label><input class="form-control mb-3" type="number" name="nombre_chambres" min="1" max="<?=$room['quantite']?>" value="<?=e($_POST['nombre_chambres']??1)?>" required></div></div><div class="alert alert-info">Le montant sera calculé selon le prix par nuit, les dates et le nombre de chambres. Paiement à l’hôtel dans cette première version.</div><button class="btn btn-primary">Confirmer la demande →</button></form></section><?php require __DIR__.'/includes/footer.php';?>